  position: "absolute",
  bottom: "12px",
  right: "12px",
  display: "flex",
  alignItems: "center",
  gap: "2px",
  padding: "4px",
  borderRadius: "8px",
  background: "${n.bg}",
  boxShadow: "${n.shadow}",
